/**
 * @planks-provisional("features/new-todo.feature:A new todo appears in the list after pressing Enter")
 * @planks-provisional("features/new-todo.feature:The new todo input is cleared after adding a todo")
 * @planks-provisional("features/new-todo.feature:Whitespace-only input does not create a todo")
 * @planks-provisional("features/new-todo.feature:Leading and trailing whitespace is trimmed from the title")
 * @planks-provisional("features/new-todo.feature:The new todo input is focused on page load")
 * @planks-provisional("features/new-todo.feature:Multiple todos can be added sequentially")
 * @planks-provisional("features/toggle-all.feature:Clicking toggle-all marks all todos as completed")
 * @planks-provisional("features/toggle-all.feature:Clicking toggle-all when all are completed marks all as active")
 * @planks-provisional("features/toggle-all.feature:Toggle-all is unchecked when at least one todo is active")
 * @planks-provisional("features/toggle-all.feature:Toggle-all is checked when all todos are completed")
 * @planks-provisional("features/item.feature:Clicking the checkbox marks a todo as completed")
 * @planks-provisional("features/item.feature:Clicking the checkbox on a completed todo marks it as active")
 * @planks-provisional("features/item.feature:Double-clicking the label activates editing mode")
 * @planks-provisional("features/item.feature:The edit input contains the current title")
 * @planks-provisional("features/item.feature:Pressing Enter saves the edit and exits editing mode")
 * @planks-provisional("features/item.feature:Blurring the edit input saves the edit")
 * @planks-provisional("features/item.feature:Trimming whitespace from edit input on save")
 * @planks-provisional("features/item.feature:Empty edit input deletes the todo")
 * @planks-provisional("features/item.feature:Pressing Escape discards the edit")
 * @planks-provisional("features/item.feature:Hovering over a todo shows the destroy button")
 * @planks-provisional("features/item.feature:Clicking the destroy button removes the todo")
 * @planks-provisional("features/counter.feature:Counter shows the count of active todos")
 * @planks-provisional("features/counter.feature:Counter uses singular form for one item")
 * @planks-provisional("features/counter.feature:Counter uses plural form for multiple items")
 * @planks-provisional("features/counter.feature:Counter shows zero items when all are completed")
 * @planks-provisional("features/clear-completed.feature:Clicking clear completed removes completed todos")
 * @planks-provisional("features/clear-completed.feature:Clear completed button is visible when completed todos exist")
 * @planks-provisional("features/clear-completed.feature:Clear completed button is hidden when no completed todos exist")
 * @planks-provisional("features/clear-completed.feature:Clear completed button is hidden when the list is empty")
 * @planks-provisional("features/persistence.feature:Todos are stored in localStorage")
 * @planks-provisional("features/persistence.feature:Completed status is persisted")
 * @planks-provisional("features/persistence.feature:The localStorage key is \"todos-vanillajs\"")
 * @planks-provisional("features/persistence.feature:Editing mode is not persisted")
 * @planks-provisional("features/routing.feature:Default route shows all todos")
 * @planks-provisional("features/routing.feature:Active route shows only active todos")
 * @planks-provisional("features/routing.feature:Completed route shows only completed todos")
 * @planks-provisional("features/routing.feature:The active filter persists across reloads")
 * @planks-provisional("features/routing.feature:Completed items hidden by active filter are not removed")
 * @planks-provisional("features/routing.feature:Toggling an item in filtered view hides it from that filter")
 * @planks-provisional("features/visibility.feature:Main and footer are hidden when there are no todos")
 * @planks-provisional("features/visibility.feature:Main and footer are shown when todos exist")
 */
(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;
	var STORAGE_KEY = 'todos-vanillajs';

	/**
	 * @planks-provisional("features/persistence.feature:Todos are stored in localStorage")
	 */
	var Utils = {
		uuid: function () {
			return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
				var r = Math.random() * 16 | 0;
				var v = c === 'x' ? r : (r & 0x3 | 0x8);
				return v.toString(16);
			});
		},
		pluralize: function (count, word) {
			return count === 1 ? word : word + 's';
		},
		store: function (namespace, data) {
			if (arguments.length > 1) {
				return localStorage.setItem(namespace, JSON.stringify(data));
			} else {
				var store = localStorage.getItem(namespace);
				return (store && JSON.parse(store)) || [];
			}
		}
	};

	/**
	 * @planks-provisional("features/routing.feature:Default route shows all todos")
	 */
	function App() {
		this.todos = Utils.store(STORAGE_KEY);
		this.currentRoute = this._getRoute();
		this._bindElements();
		this._bindEvents();
		this.render();
	}

	/**
	 * @planks-provisional("features/visibility.feature:Main and footer are hidden when there are no todos")
	 */
	App.prototype._bindElements = function () {
		this.newTodoInput = document.querySelector('.new-todo');
		this.todoList = document.querySelector('.todo-list');
		this.toggleAllCheckbox = document.getElementById('toggle-all');
		this.mainSection = document.querySelector('.main');
		this.footer = document.querySelector('.footer');
		this.todoCount = document.querySelector('.todo-count');
		this.clearCompletedBtn = document.querySelector('.clear-completed');
		this.filters = document.querySelectorAll('.filters a');
	};

	/**
	 * @planks-provisional("features/new-todo.feature:The new todo input is focused on page load")
	 */
	App.prototype._bindEvents = function () {
		var self = this;

		this.newTodoInput.addEventListener('keydown', function (e) {
			if (e.keyCode === ENTER_KEY) {
				self._addTodo();
			}
		});

		this.toggleAllCheckbox.addEventListener('change', function () {
			self._toggleAll(this.checked);
		});

		this.clearCompletedBtn.addEventListener('click', function () {
			self._clearCompleted();
		});

		this.filters.forEach(function (link) {
			link.addEventListener('click', function (e) {
				e.preventDefault();
				var hash = this.getAttribute('href');
				if (self.currentRoute !== hash) {
					window.location.hash = hash;
					window.dispatchEvent(new Event('hashchange'));
				}
			});
		});

		window.addEventListener('hashchange', function () {
			self.currentRoute = self._getRoute();
			self.render();
		});
	};

	/**
	 * @planks-provisional("features/routing.feature:Default route shows all todos")
	 */
	App.prototype._getRoute = function () {
		var hash = window.location.hash || '#/';
		return hash === '#/active' ? '#/active' : hash === '#/completed' ? '#/completed' : '#/';
	};

	/**
	 * @planks-provisional("features/new-todo.feature:A new todo appears in the list after pressing Enter")
	 * @planks-provisional("features/new-todo.feature:Whitespace-only input does not create a todo")
	 * @planks-provisional("features/new-todo.feature:Leading and trailing whitespace is trimmed from the title")
	 */
	App.prototype._addTodo = function () {
		var title = this.newTodoInput.value.trim();
		if (!title) return;

		this.todos.push({
			id: Utils.uuid(),
			title: title,
			completed: false
		});

		this.newTodoInput.value = '';
		this._save();
		this.render();
	};

	/**
	 * @planks-provisional("features/toggle-all.feature:Clicking toggle-all marks all todos as completed")
	 * @planks-provisional("features/toggle-all.feature:Clicking toggle-all when all are completed marks all as active")
	 */
	App.prototype._toggleAll = function (completed) {
		this.todos.forEach(function (todo) {
			todo.completed = completed;
		});
		this._save();
		this.render();
	};

	/**
	 * @planks-provisional("features/clear-completed.feature:Clicking clear completed removes completed todos")
	 */
	App.prototype._clearCompleted = function () {
		this.todos = this.todos.filter(function (todo) {
			return !todo.completed;
		});
		this._save();
		this.render();
	};

	/**
	 * @planks-provisional("features/persistence.feature:Todos are stored in localStorage")
	 */
	App.prototype._save = function () {
		Utils.store(STORAGE_KEY, this.todos);
	};

	/**
	 * @planks-provisional("features/item.feature:Clicking the checkbox marks a todo as completed")
	 */
	App.prototype._toggleTodo = function (id) {
		this.todos.forEach(function (todo) {
			if (todo.id === id) {
				todo.completed = !todo.completed;
			}
		});
		this._save();
		this.render();
	};

	/**
	 * @planks-provisional("features/item.feature:Clicking the destroy button removes the todo")
	 */
	App.prototype._destroyTodo = function (id) {
		this.todos = this.todos.filter(function (todo) {
			return todo.id !== id;
		});
		this._save();
		this.render();
	};

	/**
	 * @planks-provisional("features/item.feature:Double-clicking the label activates editing mode")
	 * @planks-provisional("features/item.feature:The edit input contains the current title")
	 */
	App.prototype._startEditing = function (id) {
		var todoEl = this.todoList.querySelector('[data-id="' + id + '"]');
		if (todoEl) {
			todoEl.classList.add('editing');
			var editInput = todoEl.querySelector('.edit');
			editInput.focus();
		}
	};

	/**
	 * @planks-provisional("features/item.feature:Pressing Enter saves the edit and exits editing mode")
	 * @planks-provisional("features/item.feature:Blurring the edit input saves the edit")
	 * @planks-provisional("features/item.feature:Trimming whitespace from edit input on save")
	 * @planks-provisional("features/item.feature:Empty edit input deletes the todo")
	 */
	App.prototype._saveEdit = function (id, newTitle) {
		var trimmed = newTitle.trim();
		if (!trimmed) {
			this._destroyTodo(id);
			return;
		}
		this.todos.forEach(function (todo) {
			if (todo.id === id) {
				todo.title = trimmed;
			}
		});
		this._save();
		this.render();
	};

	/**
	 * @planks-provisional("features/item.feature:Pressing Escape discards the edit")
	 */
	App.prototype._cancelEdit = function (id) {
		var todoEl = this.todoList.querySelector('[data-id="' + id + '"]');
		if (todoEl) {
			todoEl.classList.remove('editing');
		}
	};

	/**
	 * @planks-provisional("features/visibility.feature:Main and footer are hidden when there are no todos")
	 * @planks-provisional("features/visibility.feature:Main and footer are shown when todos exist")
	 * @planks-provisional("features/counter.feature:Counter shows the count of active todos")
	 * @planks-provisional("features/counter.feature:Counter uses singular form for one item")
	 * @planks-provisional("features/counter.feature:Counter uses plural form for multiple items")
	 * @planks-provisional("features/counter.feature:Counter shows zero items when all are completed")
	 * @planks-provisional("features/toggle-all.feature:Toggle-all is unchecked when at least one todo is active")
	 * @planks-provisional("features/toggle-all.feature:Toggle-all is checked when all todos are completed")
	 * @planks-provisional("features/clear-completed.feature:Clear completed button is visible when completed todos exist")
	 * @planks-provisional("features/clear-completed.feature:Clear completed button is hidden when no completed todos exist")
	 * @planks-provisional("features/clear-completed.feature:Clear completed button is hidden when the list is empty")
	 * @planks-provisional("features/routing.feature:Active route shows only active todos")
	 * @planks-provisional("features/routing.feature:Completed route shows only completed todos")
	 */
	App.prototype.render = function () {
		var self = this;
		var activeTodos = this.todos.filter(function (t) { return !t.completed; });
		var completedTodos = this.todos.filter(function (t) { return t.completed; });
		var hasTodos = this.todos.length > 0;

		// Visibility of main and footer
		this.mainSection.style.display = hasTodos ? 'block' : 'none';
		this.footer.style.display = hasTodos ? 'block' : 'none';

		// Counter
		var activeCount = activeTodos.length;
		this.todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + Utils.pluralize(activeCount, 'item') + ' left';

		// Toggle-all
		this.toggleAllCheckbox.checked = hasTodos && activeCount === 0;

		// Clear completed visibility
		this.clearCompletedBtn.style.display = completedTodos.length > 0 ? 'block' : 'none';

		// Filters
		this.filters.forEach(function (link) {
			var href = link.getAttribute('href');
			link.classList.toggle('selected', href === self.currentRoute);
		});

		// Filter todos based on route
		var visibleTodos;
		if (this.currentRoute === '#/active') {
			visibleTodos = activeTodos;
		} else if (this.currentRoute === '#/completed') {
			visibleTodos = completedTodos;
		} else {
			visibleTodos = this.todos;
		}

		// Render todo list
		this.todoList.innerHTML = '';
		visibleTodos.forEach(function (todo) {
			var li = document.createElement('li');
			li.setAttribute('data-id', todo.id);
			li.className = todo.completed ? 'completed' : '';

			var div = document.createElement('div');
			div.className = 'view';

			var checkbox = document.createElement('input');
			checkbox.className = 'toggle';
			checkbox.type = 'checkbox';
			checkbox.checked = todo.completed;
			checkbox.addEventListener('change', function () {
				self._toggleTodo(todo.id);
			});

			var label = document.createElement('label');
			label.textContent = todo.title;
			label.addEventListener('dblclick', function () {
				self._startEditing(todo.id);
			});

			var destroyBtn = document.createElement('button');
			destroyBtn.className = 'destroy';
			destroyBtn.addEventListener('click', function () {
				self._destroyTodo(todo.id);
			});

			var editInput = document.createElement('input');
			editInput.className = 'edit';
			editInput.value = todo.title;
			editInput.addEventListener('blur', function () {
				self._saveEdit(todo.id, this.value);
			});
			editInput.addEventListener('keydown', function (e) {
				if (e.keyCode === ENTER_KEY) {
					self._saveEdit(todo.id, this.value);
				} else if (e.keyCode === ESCAPE_KEY) {
					self._cancelEdit(todo.id);
				}
			});

			div.appendChild(checkbox);
			div.appendChild(label);
			div.appendChild(destroyBtn);
			li.appendChild(div);
			li.appendChild(editInput);
			self.todoList.appendChild(li);
		});
	};

	// Initialize the app when the DOM is ready
	var app = new App();
})();

